        return False
    if n % 2 == 0:
        return n == 2
    r = int(math.isqrt(n))
    for f in range(3, r+1, 2):
        if n % f == 0:
            return False
    return True
if not is_prime(alpha):
    return (False, None)
if not (alpha > min_a):
    return (False, None)
if alpha % q_den != r_mod % q_den:
    return (False, None)
